CREATE TABLE smartform.msf_request_cancel (
    request_key numeric(20,0) NOT NULL,
    cret_ip character varying(20),
    cret_dt timestamp without time zone,
    cret_id character varying(50),
    amd_ip character varying(20),
    amd_dt timestamp without time zone,
    amd_id character varying(50),
    manager_cd character varying(20) NOT NULL,
    manager_nm character varying(100),
    agent_cd character varying(20) NOT NULL,
    agent_nm character varying(100),
    shop_cd character varying(20),
    shop_nm character varying(100),
    real_shop_nm character varying(100),
    cpnt_id character varying(20),
    cpnt_nm character varying(100),
    cntpnt_shop_cd character varying(20),
    cntpnt_shop_nm character varying(100),
    oper_type_cd character varying(10) NOT NULL,
    cstmr_type_cd character varying(10) NOT NULL,
    identity_cert_type_cd character varying(2),
    cancel_mobile_no character varying(13),
    contract_num character varying(10),
    auth_info character varying(255),
    identity_type_cd character varying(2),
    identity_issu_date character varying(8),
    identity_issu_region character varying(100),
    self_issu_no character varying(250),
    drive_licns_no character varying(250),
    receive_way_cd character(1) NOT NULL,
    cancel_use_company_cd character varying(20),
    pay_amt numeric(22,0),
    pnlt_amt numeric(22,0),
    last_sum_amt numeric(22,0),
    instamt_mnth_cnt character varying(2),
    instamt_mnth_amt numeric(22,0),
    benefit_agree_yn character(1) DEFAULT 'N'::bpchar NOT NULL,
    clause_cntr_del_yn character(1) DEFAULT 'N'::bpchar NOT NULL,
    etc_agree_yn character(1) DEFAULT 'N'::bpchar NOT NULL,
    memo character varying(6000),
    open_req_dt timestamp without time zone,
    regst_id character varying(50),
    req_in_dt timestamp without time zone,
    proc_dt timestamp without time zone,
    proc_cd character varying(2),
    rec_yn character(1) DEFAULT 'N'::bpchar NOT NULL,
    res_cd character varying(10),
    res_msg character varying(100),
    res_no character varying(20),
    scan_id character varying(50),
    app_form_yn character(1) DEFAULT 'N'::bpchar NOT NULL,
    app_form_xml_yn character(1) DEFAULT 'N'::bpchar NOT NULL,
    file_nm character varying(300),
    file_mask_nm character varying(300),
    parent_scan_id character varying(32)
);


