-- Name: msf_request_cstmr_temp; Type: TABLE; Schema: smartform; Owner: -
--

CREATE TABLE smartform.msf_request_cstmr_temp (
    request_key numeric(20,0) NOT NULL,
    cret_ip character varying(20),
    cret_dt timestamp without time zone,
    cret_id character varying(50),
    amd_ip character varying(20),
    amd_dt timestamp without time zone,
    amd_id character varying(50),
    cstmr_nm character varying(100),
    cstmr_native_rrn character varying(250),
    cstmr_native_birth character varying(10),
    cstmr_native_gender_cd character(1),
    cstmr_private_cname character varying(100),
    cstmr_private_biz_no character varying(20),
    cstmr_foreigner_rrn character varying(250),
    cstmr_foreigner_birth character varying(10),
    cstmr_foreigner_gender_cd character(1),
    cstmr_foreigner_pn character varying(250),
    cstmr_foreigner_country_cd character varying(10),
    cstmr_foreigner_nation character varying(100),
    cstmr_foreigner_visa_no character varying(20),
    cstmr_foreigner_vdate_start_date character varying(14),
    cstmr_foreigner_vdate_end_date character varying(14),
    cstmr_juridical_cname character varying(100),
    cstmr_juridical_rrn character varying(250),
    cstmr_juridical_biz_no character varying(20),
    cstmr_juridical_rep_nm character varying(100),
    upjn_cd character varying(10),
    bcu_sbst character varying(100),
    cstmr_juridical_user_nm character varying(100),
    cstmr_juridical_birth character varying(10),
    cstmr_visit_type_cd character varying(3),
    cstmr_tel_fn_no character varying(3),
    cstmr_tel_mn_no character varying(4),
    cstmr_tel_rn_no character varying(4),
    cstmr_mobile_fn_no character varying(3),
    cstmr_mobile_mn_no character varying(4),
    cstmr_mobile_rn_no character varying(4),
    cstmr_zipcd character varying(6),
    cstmr_adr character varying(255),
    cstmr_adr_dtl character varying(255),
    cstmr_adr_bjd character varying(255),
    cstmr_email_adr character varying(100),
    cstmr_email_receive_yn character(1) DEFAULT 'N'::bpchar NOT NULL,
    cstmr_receive_tel_fn_no character varying(3),
    cstmr_receive_tel_nm_no character varying(4),
    cstmr_receive_tel_rn_no character varying(4),
    cstmr_private_biz_no_issu_date character varying(8),
    cstmr_juridical_biz_no_issu_date character varying(8)
);


