--
-- Name: msf_request_osst; Type: TABLE; Schema: smartform; Owner: -
--

CREATE TABLE smartform.msf_request_osst (
    mvno_ord_no character varying(14),
    seq numeric(22,0) NOT NULL,
    cret_ip character varying(20),
    cret_dt timestamp without time zone,
    cret_id character varying(50),
    amd_ip character varying(20),
    amd_dt timestamp without time zone,
    amd_id character varying(50),
    osst_ord_no character varying(14),
    prgr_stat_cd character varying(3),
    cust_id character varying(10),
    svc_cntr_no character varying(10) NOT NULL,
    rslt_cd character varying(25),
    rslt_msg character varying(1000),
    rslt_date character varying(14),
    nstep_global_id character varying(25),
    prdc_chk_noti_msg character varying(1500),
    np_bcntr_type_cd character(1),
    np_fee numeric(22,0),
    np_nchrg_amt numeric(22,0),
    np_pnlt_amt numeric(22,0),
    np_unpay_amt numeric(22,0),
    np_hndst_inst_amt numeric(22,0),
    np_prepay_amt numeric(22,0),
    np_base_chrg_amt numeric(22,0),
    np_ntnl_chrg_amt numeric(22,0),
    np_intl_chrg_amt numeric(22,0),
    np_add_chrg_amt numeric(22,0),
    np_etc_chrg_amt numeric(22,0),
    np_vat numeric(22,0),
    np_rmn_strt_date character varying(8),
    np_rmn_end_date character varying(8),
    tlph_no_stat_cd character varying(2),
    asgn_agnc_id character varying(10),
    tlph_no_own_cmpn_cd character varying(3),
    open_svc_ind_cd character varying(2),
    encd_tlph_no character varying(24),
    tlph_no character varying(11),
    if_type_cd character varying(4),
    reg_dt timestamp without time zone,
    dcla_deed_eft_date character varying(8),
    sbsc_lmt_qnty character varying(9),
    sbsc_circuit_qnty character varying(9),
    dlnq_amt numeric(9,0),
    eicc_id character varying(19)
);


