    prod_amt numeric(15,0),
    insr_cd character varying(2),
    clause_insurance_yn character(1) DEFAULT 'N'::bpchar,
    clause_insr_prod_yn character(1) DEFAULT 'N'::bpchar,
    insr_auth_info character varying(255),
    usim_buy_type_cd character varying(10),
    req_usim_sn character varying(50),
    req_usim_nm character varying(30),
    icc_id character varying(30),
    eid character varying(32),
    imei1 character varying(19),
    imei2 character varying(19),
    esim_phone_id character varying(20),
    upload_phone_srl_no numeric(22,0),
    prnts_tgt_type_cd character varying(2),
    prnts_mobile_no character varying(11),
    prnts_contract_num character varying(10),
    prnts_cstmr_nm character varying(100),
    prnts_cstmr_birth character varying(10),
    prnts_cstmr_gender_cd character(1),
    prnts_soc_cd character varying(20),
    prnts_soc_nm character varying(100),
    prnts_prod_id character varying(20),
    prnts_prod_nm character varying(100),
    combine_id character varying(20),
    combine_solo_type_yn character(1) DEFAULT 'N'::bpchar,
    combine_solo_yn character(1) DEFAULT 'N'::bpchar,
    proc_dt timestamp without time zone,
    proc_cd character varying(2),
    res_cd character varying(10),
    res_msg character varying(100),
    res_no character varying(20),
    scan_id character varying(50),
    app_form_yn character(1) DEFAULT 'N'::bpchar,
    app_form_xml_yn character(1) DEFAULT 'N'::bpchar,
    file_nm character varying(300),
    file_mask_nm character varying(300),
    parent_scan_id character varying(32),
    svc_chg_type_cd character(1),
    dis_prmt_id character varying(30),
    dis_prmt_amt numeric(7,0)
);


